// Объявление
int arr[5];              // неинициализирован — содержит мусор!
int arr2[5] = {1, 2, 3}; // {1, 2, 3, 0, 0} — остальные элементы value-initialized (0)
int arr3[] = {1, 2, 3, 4, 5}; // размер выводится автоматически из количества инициализаторов

// Доступ
arr[0] = 10;
int x = arr[2];          // без проверки границ!
// arr[10] = 5;          // UB: выход за границы — неопределённое поведение!

// Размер
sizeof(arr) / sizeof(arr[0])  // 5 (только для массивов, не указателей!)
std::size(arr)                // C++17, работает и для массивов, и для контейнеров

void func(int* ptr, size_t size);  // принимает указатель

int arr[5] = {1,2,3,4,5};
func(arr, 5);  // arr неявно преобразуется в int* (утеря размера!)
// Внутри func: sizeof(ptr) == sizeof(int*), а не 5*sizeof(int)

int arr[] = {1, 2, 3, 4, 5};

for (int i = 0; i < 5; ++i) { ... }
for (int x : arr) { ... }  // range-based for работает!

std::string s = "hello";
for (char c : s) std::cout << c << ' ';  // h e l l o — перебор символов
for (auto& c : s) c = std::toupper(c);   // HELLO — модификация через ссылку

// std::string_view — не владеющий взгляд на строку (zero-copy)
#include <string_view>

void print(std::string_view sv) {  // принимает string, char*, string_view
    std::cout << sv << '\n';
}

std::string s = "hello";
print(s);           // OK — неявное преобразование
print("world");     // OK — строковый литерал
print(std::string_view(s, 2, 3)); // "llo" — подпоследовательность
